import React from "react";
import { useState } from "react";
import { BrowserRouter, Routes, Route, Link, useParams } from "react-router-dom";
import "./taskflow.css";

function Taskflow() {
    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [tasks, setTasks] = useState([
        { id: 1, title: "Set up project repo", completed: false, createdAt: "Nov 3, 2026" },
        { id: 2, title: "Write feature list", completed: true, createdAt: "Nov 3, 2026" },
        { id: 3, title: "Build add-task form", completed: false, createdAt: "Nov 3, 2026" },
    ]);

    function addTask() {
        if (newTask.trim() === "") return;
        setTasks([
            ...tasks,
            { id: Date.now(), title: newTask, completed: false, createdAt: new Date().toDateString() },
        ]);
        setNewTask("");
    }

    function toggleTask(id) {
        setTasks(tasks.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t)));
    }

    function deleteTask(id) {
        setTasks(tasks.filter((t) => t.id !== id));
    }

    const filteredTasks = tasks.filter((t) =>
        t.title.toLowerCase().includes(search.toLowerCase())
    );

    // List page
    const listPage = (
        <div className="card">
            <h2>List View — "/"</h2>

            <input
                className="text-box"
                type="text"
                placeholder="Search tasks..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />

            <div className="add-row">
                <input
                    className="text-box"
                    type="text"
                    placeholder="Add a new task..."
                    value={newTask}
                    onChange={(e) => setNewTask(e.target.value)}
                />
                <button className="add-btn" onClick={addTask}>Add</button>
            </div>

            {filteredTasks.map((task) => (
                <div className="task" key={task.id}>
                    <div>
                        <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => toggleTask(task.id)}
                        />
                        <Link to={"/tasks/" + task.id} className={task.completed ? "done" : ""}>
                            {task.title}
                        </Link>
                    </div>
                    <button onClick={() => deleteTask(task.id)}>Delete</button>
                </div>
            ))}
        </div>
    );

    // Detail page
    function Detail() {
        const { id } = useParams();
        const task = tasks.find((t) => t.id === Number(id));

        if (!task) return <div className="card">Task not found</div>;

        return (
            <div className="card">
                <h2>Detail View — "/tasks/:id"</h2>
                <Link to="/">← Back to list</Link>
                <p>Title: {task.title}</p>
                <p>Status: {task.completed ? "Completed" : "Pending"}</p>
                <p>Created: {task.createdAt}</p>
            </div>
        );
    }

    return (
        <BrowserRouter>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>

            <Routes>
                <Route path="/" element={listPage} />
                <Route path="/tasks/:id" element={<Detail />} />
            </Routes>
        </BrowserRouter>
    );
}

export default Taskflow
